import{_ as t,o as a,c as r,a3 as i}from"./chunks/framework.DBpCFmh2.js";const h=JSON.parse('{"title":"工件声明系统","description":"本文件聚焦“工件（Artifacts）声明系统”，即 AI 助手在完成任务后，如何把 Agent 执行过程中产生的文件、目录以及 AI 显式声明的产物，统一提取、合并、校验并展示给用户的完整链路。","frontmatter":{"title":"工件声明系统","description":"本文件聚焦“工件（Artifacts）声明系统”，即 AI 助手在完成任务后，如何把 Agent 执行过程中产生的文件、目录以及 AI 显式声明的产物，统一提取、合并、校验并展示给用户的完整链路。"},"headers":[],"relativePath":"Chrome-扩展核心/Side-Panel-界面架构/UI-组件库/Markdown-渲染引擎/工件声明系统/index.md","filePath":"Chrome-扩展核心/Side-Panel-界面架构/UI-组件库/Markdown-渲染引擎/工件声明系统/index.md","lastUpdated":null}'),l={name:"Chrome-扩展核心/Side-Panel-界面架构/UI-组件库/Markdown-渲染引擎/工件声明系统/index.md"};function o(n,e,s,c,d,g){return a(),r("div",null,[...e[0]||(e[0]=[i(`<h1 id="工件声明系统" tabindex="-1">工件声明系统 <a class="header-anchor" href="#工件声明系统" aria-label="Permalink to &quot;工件声明系统&quot;">​</a></h1><details class="details custom-block"><summary>本文引用的源码文件</summary><p><strong>本文引用的文件</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/artifacts-manager.js" target="_blank" rel="noreferrer">src/side_panel/artifacts-manager.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-manager.js" target="_blank" rel="noreferrer">src/side_panel/chat-manager.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js" target="_blank" rel="noreferrer">src/background/react-loop.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/unit/artifact-declare-linkify.unit.test.js" target="_blank" rel="noreferrer">test/unit/artifact-declare-linkify.unit.test.js</a></li></ul></details><h2 id="目录" tabindex="-1">目录 <a class="header-anchor" href="#目录" aria-label="Permalink to &quot;目录&quot;">​</a></h2><ol><li><a href="#引言">引言</a></li><li><a href="#项目结构定位">项目结构定位</a></li><li><a href="#核心组件">核心组件</a></li><li><a href="#架构总览">架构总览</a></li><li><a href="#详细组件分析">详细组件分析</a></li><li><a href="#依赖关系分析">依赖关系分析</a></li><li><a href="#性能与复杂度">性能与复杂度</a></li><li><a href="#故障排查指南">故障排查指南</a></li><li><a href="#结论">结论</a></li></ol><h2 id="引言" tabindex="-1">引言 <a class="header-anchor" href="#引言" aria-label="Permalink to &quot;引言&quot;">​</a></h2><p>本文件聚焦“工件（Artifacts）声明系统”，即 AI 助手在完成任务后，如何把 Agent 执行过程中产生的文件、目录以及 AI 显式声明的产物，统一提取、合并、校验并展示给用户的完整链路。该系统由两部分组成：</p><ul><li><strong>静态工件提取</strong>：从任务执行日志中解析 <code>agent_exec</code>、<code>agent_file</code>、<code>file_upload</code> 等工具调用，推断写文件、创建目录、删除路径等操作。</li><li><strong>AI 声明工件</strong>：从助手最终回答文本中解析形如 <code>[[artifact:路径|可选说明]]</code> 的标记，并与静态工件合并去重，补充说明信息。</li></ul><p>该系统的实现位于侧边栏模块，核心逻辑集中在 <code>src/side_panel/artifacts-manager.js</code>，并在聊天消息渲染流程中被 <code>src/side_panel/chat-manager.js</code> 消费；背景进程中的 ReAct 执行循环则负责生成可供分析的 <code>executionLog</code>。</p><h2 id="项目结构定位" tabindex="-1">项目结构定位 <a class="header-anchor" href="#项目结构定位" aria-label="Permalink to &quot;项目结构定位&quot;">​</a></h2><p>工件声明系统属于扩展端 MV3 Service Worker 架构下的侧边栏功能，不直接修改 Agent 源码，而是通过读取已持久化的任务执行日志和助手回复内容完成工件发现。</p><pre class="mermaid">graph TB
subgraph &quot;侧边栏&quot;
CM[&quot;聊天管理器&lt;br/&gt;chat-manager.js&quot;]
AM[&quot;工件管理器&lt;br/&gt;artifacts-manager.js&quot;]
end
subgraph &quot;背景进程&quot;
RL[&quot;ReAct 执行循环&lt;br/&gt;react-loop.js&quot;]
end
RL --&gt; |&quot;生成 executionLog&quot;| CM
CM --&gt; |&quot;传入 executionLog 与原始回复&quot;| AM
AM --&gt; |&quot;返回工件列表&quot;| CM
CM --&gt; |&quot;渲染按钮/弹窗&quot;| AM
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/artifacts-manager.js#L949-L1349" target="_blank" rel="noreferrer">src/side_panel/artifacts-manager.js#L949-L1349</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-manager.js#L2274-L2328" target="_blank" rel="noreferrer">src/side_panel/chat-manager.js#L2274-L2328</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js#L850-L850" target="_blank" rel="noreferrer">src/background/react-loop.js#L850-L850</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/artifacts-manager.js#L1-L10" target="_blank" rel="noreferrer">src/side_panel/artifacts-manager.js#L1-L10</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-manager.js#L2268-L2328" target="_blank" rel="noreferrer">src/side_panel/chat-manager.js#L2268-L2328</a></li></ul><h2 id="核心组件" tabindex="-1">核心组件 <a class="header-anchor" href="#核心组件" aria-label="Permalink to &quot;核心组件&quot;">​</a></h2><p>工件声明系统对外暴露的关键能力可归纳为以下接口：</p><table tabindex="0"><thead><tr><th>接口</th><th>所在文件</th><th>职责</th><th>输入</th><th>输出</th></tr></thead><tbody><tr><td><code>extractArtifactsFromExecutionLog</code></td><td>artifacts-manager.js</td><td>从执行日志中提取静态工件</td><td><code>executionLog</code> 数组</td><td>工件数组</td></tr><tr><td><code>parseDeclaredArtifactsFromText</code></td><td>artifacts-manager.js</td><td>从助手回复文本解析 <code>[[artifact:...]]</code></td><td>字符串</td><td>声明工件数组</td></tr><tr><td><code>mergeDeclaredArtifacts</code></td><td>artifacts-manager.js</td><td>合并静态工件与声明工件并按路径去重</td><td>静态工件数组、声明工件数组</td><td>合并后的工件数组</td></tr><tr><td><code>buildArtifactsForMessage</code></td><td>artifacts-manager.js</td><td>一站式构建消息级工件</td><td>执行日志、原始回复文本</td><td>最终工件数组</td></tr><tr><td><code>preFilterDeletedArtifacts</code></td><td>artifacts-manager.js</td><td>同步移除已标记删除的工件</td><td>工件数组</td><td>过滤后的数量</td></tr><tr><td><code>filterInvalidArtifacts</code></td><td>artifacts-manager.js</td><td>异步过滤工作目录外及不存在文件</td><td>工件数组</td><td>是否发生变化的布尔值</td></tr><tr><td><code>validateArtifactsAsync</code></td><td>artifacts-manager.js</td><td>触发异步验证并更新徽章计数</td><td>工件数组、按钮元素</td><td>Promise</td></tr><tr><td><code>showArtifactsModal</code></td><td>artifacts-manager.js</td><td>打开工件弹窗，支持排序、下载、定位、预览</td><td>工件数组、源按钮</td><td>无</td></tr></tbody></table><p>这些接口共同构成“提取 → 声明 → 合并 → 预过滤 → 异步校验 → UI 展示”的流水线。</p><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/artifacts-manager.js#L949-L1349" target="_blank" rel="noreferrer">src/side_panel/artifacts-manager.js#L949-L1349</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/artifacts-manager.js#L1661-L1783" target="_blank" rel="noreferrer">src/side_panel/artifacts-manager.js#L1661-L1783</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/artifacts-manager.js#L1792-L1933" target="_blank" rel="noreferrer">src/side_panel/artifacts-manager.js#L1792-L1933</a></li></ul><h2 id="架构总览" tabindex="-1">架构总览 <a class="header-anchor" href="#架构总览" aria-label="Permalink to &quot;架构总览&quot;">​</a></h2><p>工件声明系统的数据流可以概括为三个阶段：</p><ol><li><p><strong>数据准备阶段</strong></p><ul><li>背景进程执行 Agent 工具，产生结构化执行日志。</li><li>聊天管理器将执行日志与助手回复文本注入到消息 DOM 的 <code>data-*</code> 属性中。</li></ul></li><li><p><strong>工件构建阶段</strong></p><ul><li>聊天管理器调用静态提取函数，得到基础工件集合。</li><li>若存在声明工件，则调用合并函数进行去重与说明补全。</li><li>同步预过滤已删除工件，避免无效条目进入后续流程。</li></ul></li><li><p><strong>交互与校验阶段</strong></p><ul><li>点击工件按钮时打开弹窗，渲染表格行。</li><li>异步校验工件是否仍在工作目录内且真实存在。</li><li>根据校验结果更新徽章计数、表格内容与空状态提示。</li></ul></li></ol><pre class="mermaid">sequenceDiagram
participant RL as &quot;背景执行循环&quot;
participant CM as &quot;聊天管理器&quot;
participant AM as &quot;工件管理器&quot;
participant UI as &quot;侧边栏界面&quot;
RL-&gt;&gt;CM : &quot;提供 executionLog 与助手回复&quot;
CM-&gt;&gt;AM : &quot;extractArtifactsFromExecutionLog(executionLog)&quot;
AM--&gt;&gt;CM : &quot;静态工件列表&quot;
CM-&gt;&gt;AM : &quot;parseDeclaredArtifactsFromText(回复文本)&quot;
AM--&gt;&gt;CM : &quot;声明工件列表&quot;
CM-&gt;&gt;AM : &quot;mergeDeclaredArtifacts(静态, 声明)&quot;
AM--&gt;&gt;CM : &quot;合并工件列表&quot;
CM-&gt;&gt;AM : &quot;preFilterDeletedArtifacts(工件)&quot;
AM--&gt;&gt;CM : &quot;过滤后的工件数量&quot;
CM-&gt;&gt;UI : &quot;渲染工件按钮&quot;
UI-&gt;&gt;CM : &quot;用户点击工件按钮&quot;
CM-&gt;&gt;AM : &quot;showArtifactsModal(工件, 按钮)&quot;
AM-&gt;&gt;AM : &quot;filterInvalidArtifacts(工件)&quot;
AM--&gt;&gt;UI : &quot;更新弹窗与徽章&quot;
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/artifacts-manager.js#L949-L1349" target="_blank" rel="noreferrer">src/side_panel/artifacts-manager.js#L949-L1349</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/artifacts-manager.js#L1777-L1933" target="_blank" rel="noreferrer">src/side_panel/artifacts-manager.js#L1777-L1933</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-manager.js#L2274-L2328" target="_blank" rel="noreferrer">src/side_panel/chat-manager.js#L2274-L2328</a></li></ul><h2 id="详细组件分析" tabindex="-1">详细组件分析 <a class="header-anchor" href="#详细组件分析" aria-label="Permalink to &quot;详细组件分析&quot;">​</a></h2><h3 id="静态工件提取器" tabindex="-1">静态工件提取器 <a class="header-anchor" href="#静态工件提取器" aria-label="Permalink to &quot;静态工件提取器&quot;">​</a></h3><p>静态工件提取是工件系统的核心引擎，负责从 <code>executionLog</code> 中识别三类来源：</p><ul><li><code>agent_exec</code>：解析 shell 命令链，识别写入、创建、复制、删除、脚本执行、heredoc 内联脚本等。</li><li><code>agent_file</code>：处理显式的 write/delete 操作。</li><li><code>file_upload</code>：处理上传到工作目录的文件。</li></ul><p>其关键行为包括：</p><ul><li>按时间排序执行日志，保证“先创建后删除”的时序语义正确。</li><li>维护 <code>seenPaths</code> 去重，同一路径只保留最后一次操作。</li><li>维护 <code>createdRoots</code> 记录本任务创建的目录根，用于限制观察输出兜底解析的范围。</li><li>维护 <code>deletedPaths</code> 记录删除操作，并在后处理阶段标记工件为已删除。</li><li>对 <code>ls -R</code>、<code>find</code> 等列表输出做兜底解析，但仅在确有写操作或路径位于已创建根下时才采信。</li></ul><pre class="mermaid">flowchart TD
Start([&quot;开始提取&quot;]) --&gt; Sort[&quot;按时间排序执行日志&quot;]
Sort --&gt; ScanScripts[&quot;预扫描脚本内容映射&quot;]
ScanScripts --&gt; LoopEntries{&quot;遍历执行日志&quot;}
LoopEntries --&gt; IsToolExec{&quot;是否为 tool_exec？&quot;}
IsToolExec --&gt; |否| NextEntry[&quot;跳过&quot;]
IsToolExec --&gt; |是| CheckAgentExec{&quot;是否为 agent_exec？&quot;}
CheckAgentExec --&gt; |是| ParseExec[&quot;解析命令链&lt;br/&gt;mkdir/touch/echo/cat/cp/tee/rm/heredoc&quot;]
ParseExec --&gt; TrackCwd[&quot;跟踪 cd 与工作目录&quot;]
TrackCwd --&gt; ListFallback[&quot;列表输出兜底解析 ls/find&quot;]
ListFallback --&gt; UpdateRoots[&quot;更新已创建根集合&quot;]
UpdateRoots --&gt; MarkDeleted[&quot;记录删除路径&quot;]
MarkDeleted --&gt; NextEntry
CheckAgentExec --&gt; |否| CheckAgentFile{&quot;是否为 agent_file？&quot;}
CheckAgentFile --&gt; |write| AddWrite[&quot;添加写入工件&quot;]
CheckAgentFile --&gt; |delete| MarkFileDelete[&quot;标记文件删除&quot;]
CheckAgentFile --&gt; |其他| NextEntry
AddWrite --&gt; NextEntry
MarkFileDelete --&gt; NextEntry
NextEntry --&gt; EndLoop{&quot;是否还有条目&quot;}
EndLoop --&gt; |是| LoopEntries
EndLoop --&gt; |否| PostProcess[&quot;后处理：标记被删除工件&quot;]
PostProcess --&gt; Return[&quot;返回工件列表&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/artifacts-manager.js#L949-L1265" target="_blank" rel="noreferrer">src/side_panel/artifacts-manager.js#L949-L1265</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/artifacts-manager.js#L949-L1265" target="_blank" rel="noreferrer">src/side_panel/artifacts-manager.js#L949-L1265</a></li></ul><h3 id="ai-工件声明解析与合并" tabindex="-1">AI 工件声明解析与合并 <a class="header-anchor" href="#ai-工件声明解析与合并" aria-label="Permalink to &quot;AI 工件声明解析与合并&quot;">​</a></h3><p>AI 声明工件采用固定标记格式：</p><ul><li>基本语法：<code>[[artifact:路径|可选说明]]</code></li><li>变量引用路径会被丢弃，因为无法静态确定真实文件名。</li><li>声明工件与静态工件按规范化路径去重；若命中已有静态工件，则优先补充说明字段。</li></ul><p>合并策略要点：</p><ul><li>规范化路径时去除前导 <code>./</code>，使 <code>a.xlsx</code> 与 <code>./a.xlsx</code> 视为同一文件。</li><li>若声明路径与静态绝对路径尾段一致，也视为同一文件，避免重复行。</li><li>声明工件默认类型为 <code>file</code>，工具名为 <code>declared</code>，时间戳为空，状态为 <code>unknown</code>。</li></ul><pre class="mermaid">flowchart TD
Text[&quot;助手回复文本&quot;] --&gt; Parse[&quot;正则匹配 [[artifact:路径|说明]]&quot;]
Parse --&gt; FilterVars[&quot;过滤含变量的路径&quot;]
FilterVars --&gt; DedupKey[&quot;计算规范化去重键&quot;]
DedupKey --&gt; DeclaredList[&quot;声明工件列表&quot;]
StaticList[&quot;静态工件列表&quot;] --&gt; Merge[&quot;按路径去重合并&quot;]
DeclaredList --&gt; Merge
Merge --&gt; Result[&quot;最终工件列表&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/artifacts-manager.js#L1273-L1337" target="_blank" rel="noreferrer">src/side_panel/artifacts-manager.js#L1273-L1337</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/artifacts-manager.js#L1273-L1337" target="_blank" rel="noreferrer">src/side_panel/artifacts-manager.js#L1273-L1337</a></li></ul><h3 id="聊天消息集成" tabindex="-1">聊天消息集成 <a class="header-anchor" href="#聊天消息集成" aria-label="Permalink to &quot;聊天消息集成&quot;">​</a></h3><p>聊天管理器负责把工件系统与消息 UI 连接起来：</p><ul><li>从消息元素的 <code>dataset.executionLog</code> 恢复执行日志。</li><li>从 <code>dataset.declaredArtifacts</code> 恢复声明工件。</li><li>调用静态提取与合并函数，得到最终工件列表。</li><li>同步预过滤已删除工件。</li><li>动态创建或复用工件按钮，绑定点击事件。</li><li>立即触发异步验证，更新徽章计数。</li></ul><pre class="mermaid">sequenceDiagram
participant CM as &quot;聊天管理器&quot;
participant AM as &quot;工件管理器&quot;
participant DOM as &quot;消息 DOM&quot;
CM-&gt;&gt;DOM : &quot;读取 dataset.executionLog&quot;
CM-&gt;&gt;DOM : &quot;读取 dataset.declaredArtifacts&quot;
CM-&gt;&gt;AM : &quot;extractArtifactsFromExecutionLog&quot;
AM--&gt;&gt;CM : &quot;静态工件&quot;
CM-&gt;&gt;AM : &quot;mergeDeclaredArtifacts&quot;
AM--&gt;&gt;CM : &quot;合并工件&quot;
CM-&gt;&gt;AM : &quot;preFilterDeletedArtifacts&quot;
AM--&gt;&gt;CM : &quot;过滤后数量&quot;
CM-&gt;&gt;DOM : &quot;创建/复用工件按钮&quot;
CM-&gt;&gt;AM : &quot;validateArtifactsAsync&quot;
AM--&gt;&gt;CM : &quot;异步校验完成&quot;
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-manager.js#L2274-L2328" target="_blank" rel="noreferrer">src/side_panel/chat-manager.js#L2274-L2328</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/artifacts-manager.js#L1777-L1783" target="_blank" rel="noreferrer">src/side_panel/artifacts-manager.js#L1777-L1783</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-manager.js#L2274-L2328" target="_blank" rel="noreferrer">src/side_panel/chat-manager.js#L2274-L2328</a></li></ul><h3 id="工件弹窗与交互" tabindex="-1">工件弹窗与交互 <a class="header-anchor" href="#工件弹窗与交互" aria-label="Permalink to &quot;工件弹窗与交互&quot;">​</a></h3><p>工件弹窗提供以下交互能力：</p><ul><li>按文件名、类型、时间排序。</li><li>双击文件名预览支持的文件。</li><li>单击行或定位按钮定位到工作目录。</li><li>复制文件名或按住 Ctrl/Cmd 复制绝对路径。</li><li>单文件下载或目录 Zip 下载。</li><li>异步校验后隐藏无效工件，全部无效时显示空状态。</li></ul><p>弹窗的生命周期包括：</p><ul><li>打开时重置排序状态。</li><li>渲染表头与表格行。</li><li>绑定行事件与表头排序事件。</li><li>异步校验后重新渲染或显示空状态。</li><li>ESC 关闭、遮罩挂载位置适配嵌入模式。</li></ul><pre class="mermaid">flowchart TD
Open[&quot;showArtifactsModal&quot;] --&gt; ResetSort[&quot;重置排序状态&quot;]
ResetSort --&gt; BuildOverlay[&quot;构建遮罩与弹窗 DOM&quot;]
BuildOverlay --&gt; RenderRows[&quot;渲染排序后的工件行&quot;]
RenderRows --&gt; BindEvents[&quot;绑定行事件与表头排序&quot;]
BindEvents --&gt; AsyncValidate[&quot;filterInvalidArtifacts 异步校验&quot;]
AsyncValidate --&gt; ValidCount{&quot;是否仍有有效工件？&quot;}
ValidCount --&gt; |否| ShowEmpty[&quot;显示空状态&quot;]
ValidCount --&gt; |是| UpdateRender[&quot;更新计数与表格&quot;]
ShowEmpty --&gt; Badge[&quot;更新徽章计数&quot;]
UpdateRender --&gt; Badge
Badge --&gt; Close[&quot;ESC/关闭按钮隐藏弹窗&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/artifacts-manager.js#L1792-L1933" target="_blank" rel="noreferrer">src/side_panel/artifacts-manager.js#L1792-L1933</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/artifacts-manager.js#L1792-L1933" target="_blank" rel="noreferrer">src/side_panel/artifacts-manager.js#L1792-L1933</a></li></ul><h3 id="背景执行循环与-observation-的关系" tabindex="-1">背景执行循环与 observation 的关系 <a class="header-anchor" href="#背景执行循环与-observation-的关系" aria-label="Permalink to &quot;背景执行循环与 observation 的关系&quot;">​</a></h3><p>背景进程中的 ReAct 执行循环会生成包含 <code>observation</code> 字段的执行日志。工件管理器会利用该字段进行两类增强：</p><ul><li>从 <code>agent_file</code> 或 <code>agent_exec</code> 的观察输出中尝试解析真实路径。</li><li>对 <code>ls -R</code>、<code>find</code> 等列表输出做兜底解析，反推可能的新建工件。</li></ul><p>文档注释明确指出：日志中的 <code>observation</code> 会被产物提取逻辑用于解析路径。</p><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js#L850-L850" target="_blank" rel="noreferrer">src/background/react-loop.js#L850-L850</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/artifacts-manager.js#L1180-L1183" target="_blank" rel="noreferrer">src/side_panel/artifacts-manager.js#L1180-L1183</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/artifacts-manager.js#L1097-L1137" target="_blank" rel="noreferrer">src/side_panel/artifacts-manager.js#L1097-L1137</a></li></ul><h2 id="依赖关系分析" tabindex="-1">依赖关系分析 <a class="header-anchor" href="#依赖关系分析" aria-label="Permalink to &quot;依赖关系分析&quot;">​</a></h2><p>工件声明系统内部依赖如下：</p><pre class="mermaid">graph LR
AM[&quot;artifacts-manager.js&quot;] --&gt; WM[&quot;workspace-manager.js&quot;]
AM --&gt; WP[&quot;workspace-panel.js&quot;]
AM --&gt; Utils[&quot;side_panel/utils.js&quot;]
AM --&gt; I18n[&quot;shared/i18n.js&quot;]
AM --&gt; Logger[&quot;shared/logger.js&quot;]
CM[&quot;chat-manager.js&quot;] --&gt; AM
RL[&quot;react-loop.js&quot;] --&gt; CM
</pre><ul><li><code>workspace-manager.js</code>：提供工作目录根、家目录、文件预览支持判断、文件流下载等能力。</li><li><code>workspace-panel.js</code>：提供定位文件、预览工件、解析绝对路径等能力。</li><li><code>utils.js</code>：提供 Toast、剪贴板复制等通用 UI 辅助。</li><li><code>i18n.js</code>：提供中英文文案。</li><li><code>logger.js</code>：提供错误日志记录。</li></ul><p>外部依赖方面，工件系统通过 Chrome Runtime 消息机制与背景进程通信，例如批量检查文件是否存在时发送 <code>CHECK_FILES_EXIST</code> 消息。</p><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/artifacts-manager.js#L5-L9" target="_blank" rel="noreferrer">src/side_panel/artifacts-manager.js#L5-L9</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/artifacts-manager.js#L1705-L1708" target="_blank" rel="noreferrer">src/side_panel/artifacts-manager.js#L1705-L1708</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/artifacts-manager.js#L5-L9" target="_blank" rel="noreferrer">src/side_panel/artifacts-manager.js#L5-L9</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/artifacts-manager.js#L1705-L1708" target="_blank" rel="noreferrer">src/side_panel/artifacts-manager.js#L1705-L1708</a></li></ul><h2 id="性能与复杂度" tabindex="-1">性能与复杂度 <a class="header-anchor" href="#性能与复杂度" aria-label="Permalink to &quot;性能与复杂度&quot;">​</a></h2><p>工件提取算法的时间复杂度主要受执行日志规模影响：</p><ul><li>排序：O(n log n)。</li><li>主循环：O(n)，其中每条日志可能触发命令链拆分、正则匹配、路径展开、脚本内容分析等。</li><li>列表输出兜底解析：对 <code>observation</code> 字符串做 token 化与规则过滤，近似 O(m)，m 为输出 token 数。</li><li>后处理删除标记：O(k × d)，k 为工件数，d 为删除路径数。</li></ul><p>空间复杂度方面：</p><ul><li><code>seenPaths</code>、<code>scriptContentMap</code>、<code>deletedPaths</code>、<code>createdRoots</code> 均随日志规模增长。</li><li>大体积 <code>observation</code> 或长脚本内容会增加内存占用。</li></ul><p>优化建议：</p><ul><li>对超大执行日志可考虑分页或增量构建工件。</li><li>对频繁调用的 <code>normalizePath</code>、<code>expandBraces</code> 可引入缓存。</li><li>对 Agent 离线场景保持降级策略，避免阻塞 UI。</li></ul><p>[本节为通用性能讨论，不直接分析具体代码片段]</p><h2 id="故障排查指南" tabindex="-1">故障排查指南 <a class="header-anchor" href="#故障排查指南" aria-label="Permalink to &quot;故障排查指南&quot;">​</a></h2><h3 id="工件按钮未出现" tabindex="-1">工件按钮未出现 <a class="header-anchor" href="#工件按钮未出现" aria-label="Permalink to &quot;工件按钮未出现&quot;">​</a></h3><p>可能原因：</p><ul><li>执行日志为空或格式异常。</li><li>没有检测到写文件、创建目录或上传文件操作。</li><li>所有工件均被判定为已删除、不在工作目录内或不存在。</li></ul><p>排查步骤：</p><ol><li>检查消息元素是否包含 <code>dataset.executionLog</code>。</li><li>确认 <code>extractArtifactsFromExecutionLog</code> 能返回非空列表。</li><li>检查 <code>preFilterDeletedArtifacts</code> 是否移除了全部工件。</li><li>检查 <code>filterInvalidArtifacts</code> 异步校验是否因 Agent 离线而失败。</li></ol><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-manager.js#L2274-L2328" target="_blank" rel="noreferrer">src/side_panel/chat-manager.js#L2274-L2328</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/artifacts-manager.js#L1777-L1783" target="_blank" rel="noreferrer">src/side_panel/artifacts-manager.js#L1777-L1783</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/artifacts-manager.js#L1661-L1733" target="_blank" rel="noreferrer">src/side_panel/artifacts-manager.js#L1661-L1733</a></li></ul><h3 id="工件数量与实际不符" tabindex="-1">工件数量与实际不符 <a class="header-anchor" href="#工件数量与实际不符" aria-label="Permalink to &quot;工件数量与实际不符&quot;">​</a></h3><p>可能原因：</p><ul><li>声明工件与静态工件路径不一致导致重复或遗漏。</li><li>相对路径与绝对路径未正确归一化。</li><li>工作目录未知时，目录外工件未被过滤。</li><li>Agent 离线时，存在性检查失败，系统降级保留工件。</li></ul><p>排查步骤：</p><ol><li>检查 <code>dataset.declaredArtifacts</code> 是否正确序列化。</li><li>检查 <code>mergeDeclaredArtifacts</code> 的去重键计算。</li><li>检查工作目录根是否可通过 <code>getWorkspaceRoot</code> 获取。</li><li>检查 <code>CHECK_FILES_EXIST</code> 响应是否成功。</li></ol><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/artifacts-manager.js#L1298-L1337" target="_blank" rel="noreferrer">src/side_panel/artifacts-manager.js#L1298-L1337</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/artifacts-manager.js#L1661-L1733" target="_blank" rel="noreferrer">src/side_panel/artifacts-manager.js#L1661-L1733</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-manager.js#L2284-L2286" target="_blank" rel="noreferrer">src/side_panel/chat-manager.js#L2284-L2286</a></li></ul><h3 id="工件预览或定位失败" tabindex="-1">工件预览或定位失败 <a class="header-anchor" href="#工件预览或定位失败" aria-label="Permalink to &quot;工件预览或定位失败&quot;">​</a></h3><p>可能原因：</p><ul><li>文件类型不支持预览。</li><li>工作目录面板未正确加载。</li><li>文件已被删除或路径失效。</li><li>家目录 <code>~/</code> 未展开为绝对路径。</li></ul><p>排查步骤：</p><ol><li>检查 <code>supportsPreview</code> 是否返回 true。</li><li>检查 <code>locateFileInWorkspace</code> 是否抛出错误。</li><li>检查 <code>expandHomePath</code> 是否正确展开家目录。</li><li>检查 <code>isPathInsideWorkspace</code> 是否误判路径归属。</li></ol><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/artifacts-manager.js#L1354-L1360" target="_blank" rel="noreferrer">src/side_panel/artifacts-manager.js#L1354-L1360</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/artifacts-manager.js#L1621-L1644" target="_blank" rel="noreferrer">src/side_panel/artifacts-manager.js#L1621-L1644</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/artifacts-manager.js#L1488-L1502" target="_blank" rel="noreferrer">src/side_panel/artifacts-manager.js#L1488-L1502</a></li></ul><h3 id="测试用例参考" tabindex="-1">测试用例参考 <a class="header-anchor" href="#测试用例参考" aria-label="Permalink to &quot;测试用例参考&quot;">​</a></h3><p>单元测试覆盖了工件声明链接化与历史消息恢复时的声明工件合并行为，可作为理解系统行为的参考。</p><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/unit/artifact-declare-linkify.unit.test.js#L122-L129" target="_blank" rel="noreferrer">test/unit/artifact-declare-linkify.unit.test.js#L122-L129</a></li></ul><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>工件声明系统通过“静态分析 + AI 声明 + 异步校验”的三段式架构，实现了从 Agent 执行日志到用户可见工件展示的完整闭环。其设计重点在于：</p><ul><li>对 shell 命令链、脚本内容、列表输出进行多层次解析，提高工件发现覆盖率。</li><li>通过时序把关与根目录约束，降低误报风险。</li><li>通过声明工件机制，允许 AI 显式补充静态分析无法确定的工件信息。</li><li>通过异步校验与降级策略，在 Agent 离线或文件变化时保持用户体验稳定。</li></ul><p>对于开发者而言，扩展工件系统时应优先关注：</p><ul><li>新增工具调用类型时，补充对应的路径提取逻辑。</li><li>新增声明格式时，同步更新解析与合并逻辑。</li><li>变更路径解析规则时，确保相对路径、绝对路径、家目录、工作目录边界条件正确。</li><li>变更 UI 行为时，确保事件绑定、弹窗生命周期与徽章计数保持一致。</li></ul>`,120)])])}const p=t(l,[["render",o]]);export{h as __pageData,p as default};
